/* Scripted simulation: persistent role-specific branches; no model dependency. */
window.ResidentChat={mount({id,k,r,d,t,rich,esc}){
 const host=document.querySelector('.resident-visit');if(!host)return;
 for(const sel of ['#resident-conversation','.resident-thread-status','#resident-questions','#resident-reply','#resident-next-person'])host.querySelector(sel)?.remove();
 const modal=document.querySelector('#modal');modal.classList.add('resident-dialog-open');window.TPHubWindow?.refit(modal);
 const engine=ResidentDialogue,key=id+':'+k,storeKey='tp-resident-branches-v1';let book={};try{book=JSON.parse(localStorage.getItem(storeKey))||{}}catch{}
 let state=engine.normalize(book[key]);state.visits++;const [other,slot]=d[7].split(':').map(Number),ctx={id,k,r,d,hour:IslandClock.read().hour,other:IslandBiomes.residents[other][slot]};
 const profile=window.ResidentMinutes?.person(id,k);
 const guide=profile?{why:profile.why,what:'要問出實際做了哪一步、哪裡不能寫成決定一切或擁有資產，以及該調哪份原件。',how:'先看按鈕下方的「為什麼問」。聽完回答，看「這句回答的意思」。問過工作和限制後，按「整理成會議紀錄」。'} : engine.brief(ctx);
 host.insertAdjacentHTML('beforeend',`<section class="resident-free-chat"><h3>與${esc(r[0])}聊聊</h3><div class="ask-brief"><p><b>為什麼找這位。</b>${esc(guide.why)}</p><p><b>要問出什麼。</b>${esc(guide.what)}</p><p><b>怎麼問。</b>${esc(guide.how)}</p></div>${window.ResidentMinutes?.has(id,k)?'<button type="button" class="text-button" id="open-saved-minute">打開已保存的會議紀錄</button>':''}<p class="resident-chat-status">${esc(t.name)} · ${esc(r[1])}。口述仍須用案件資料查證。</p><div class="resident-conversation"><small>${esc(t.name)} · ${state.visits>1?'再次來訪':'初次見面'}</small><p>${rich(engine.opening(ctx,state)).replaceAll('\n','<br>')}</p></div><details class="resident-old-notes"><summary>先前訪談筆錄（${state.history.length}則）</summary><div id="resident-old-history"></div></details><div class="resident-free-history" aria-live="polite"></div><div class="resident-branch-options"></div><form class="resident-chat-form"><textarea aria-label="向${esc(r[0])}自由提問" maxlength="400" placeholder="${esc(d[3])}"></textarea><button type="submit">追問</button></form><div class="resident-branch-summary" role="status"></div></section>`);
 const box=host.querySelector('.resident-free-chat'),history=box.querySelector('.resident-free-history'),choices=box.querySelector('.resident-branch-options'),form=box.querySelector('form'),input=box.querySelector('textarea'),summary=box.querySelector('[role=status]');
 const gloss=action=>{const c=window.ResidentMinutes?.card(id,k,action);return c?.means?`<p class="minute-means"><b>這句回答的意思。</b>${esc(c.means)}</p>`:''};
 const markup=h=>`<p class="resident-player-line">你：${esc(h.q)}</p><div class="resident-conversation${h.ending?' resident-counter':''}"><small>${esc(r[0])} · ${h.ending?'訪談小結':'回應'}</small><p>${rich(h.text).replaceAll('\n','<br>')}</p>${gloss(h.action)}</div>`;
 box.querySelector('#resident-old-history').innerHTML=state.history.map(markup).join('');
 const save=()=>{book[key]=state;try{localStorage.setItem(storeKey,JSON.stringify(book))}catch{}};
 const render=()=>{choices.innerHTML=engine.options(state).map(a=>{const card=window.ResidentMinutes?.card(id,k,a);const ask=a==='finish'?'整理這次的問題、回答、結論，並確認功能（含 DEMPE）、風險和資產。':(card?.ask||engine.prompts(ctx,a));const whyText=a==='finish'?'問完才按。紀錄會留著，之後在案件證據袋對照。':card?.why;const why=whyText?'<em>'+esc(whyText)+'</em>':'';return `<button type="button" data-resident-branch="${a}"><small>${esc(engine.aims[a]||'問一句')}</small><span>${esc(ask)}</span>${why}</button>`}).join('')+(state.node==='cross'?`<button type="button" data-cross-resident>去問${esc(ctx.other[0])}：${esc(ctx.other[1])} ↗</button>`:'');choices.querySelectorAll('[data-resident-branch]').forEach(b=>b.onclick=event=>{event.stopPropagation();const a=b.dataset.residentBranch;const ask=a==='finish'?'整理這次的問題、回答、結論，並確認功能（含 DEMPE）、風險和資產。':(window.ResidentMinutes?.card(id,k,a)?.ask||engine.prompts(ctx,a));reply(a,ask,b)});choices.querySelector('[data-cross-resident]')?.addEventListener('click',()=>{save();TPScene.focus(other);IslandWorld.resident(other,slot)});summary.textContent=`已探索 ${state.seen.length} 個話題 · 已見 ${state.endings.length} 種收尾。口述仍須用案件資料查證。`};
 let busy=false,pending=null;const cleanup=()=>{clearTimeout(pending);modal.classList.remove('resident-dialog-open');modal.removeEventListener('close',cleanup)};modal.addEventListener('close',cleanup,{once:true});
 const showMinute=()=>{if(!window.ResidentMinutes)return;const minute=ResidentMinutes.persist(ResidentMinutes.build(id,k,state));let slot=box.querySelector('#resident-minute');if(!slot){summary.insertAdjacentHTML('afterend','<div id="resident-minute"></div>');slot=box.querySelector('#resident-minute')}slot.innerHTML=ResidentMinutes.html(minute)+'<p class="minute-note">已存下。打開案件後，在證據袋或「會議紀錄」裡可以拿這份去對功能、DEMPE、風險和資產。</p>'};
 const reply=(action,q,button)=>{if(busy)return;busy=true;if(button){button.classList.add('is-picked');button.disabled=true}choices.querySelectorAll('button').forEach(b=>{if(b!==button)b.disabled=false});const result=engine.advance(ctx,state,action,button?null:q);state=result.state;if(q&&!result.skip&&state.history.at(-1))state.history.at(-1).q=q;save();if(!result.skip)history.insertAdjacentHTML('beforeend',markup(state.history.at(-1)));summary.textContent=result.skip?result.text:(result.ending?'會議紀錄已依這次問答寫好，在下面。其他問題仍可再問，再按一次整理會更新紀錄。':'這句先留下。看下面「這句回答的意思」。其他問題還可以分別再問。');if(result.ending)showMinute();busy=false;render()};
 box.querySelector('#open-saved-minute')?.addEventListener('click',()=>ResidentMinutes.openSaved(id+':'+k));
 form.onsubmit=e=>{e.preventDefault();const q=input.value.trim();if(!q||busy)return;input.value='';reply(engine.intent(q,state),q)};render();save();
}};
